#!/usr/bin/env bash
# Encode a video on the job's GPU and on the CPU, and compare. The source clip is generated by
# ffmpeg, so nothing is downloaded. The GPU encoder is NVENC on NVIDIA (Ubuntu's ffmpeg has it;
# the library comes with the driver) or VideoToolbox on Apple Silicon. Without either, the job
# fails rather than reporting a CPU encode as a GPU one.
#
#   transcode.sh [SECONDS] [WIDTHxHEIGHT]
set -euo pipefail
secs=${1:-20} size=${2:-1920x1080}
out=${GPULAYER_OUTPUT_DIR:-out}
mkdir -p "$out"
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

encoders=$(ffmpeg -hide_banner -encoders 2>/dev/null)
if grep -q h264_nvenc <<<"$encoders" && command -v nvidia-smi >/dev/null; then
  gpu=(-c:v h264_nvenc -preset p4 -b:v 8M) gpu_name=nvenc
elif grep -q h264_videotoolbox <<<"$encoders" && [ "$(uname)" = Darwin ]; then
  gpu=(-c:v h264_videotoolbox -b:v 8M) gpu_name=videotoolbox
else
  echo "no GPU H.264 encoder (h264_nvenc or h264_videotoolbox) in this ffmpeg" >&2
  exit 1
fi

ffmpeg -hide_banner -loglevel error -f lavfi -i "testsrc2=size=$size:rate=30:duration=$secs" \
  -c:v ffv1 "$work/source.mkv"
TIMEFORMAT=%R
enc() {  # enc NAME ARGS...
  local name=$1 t
  shift
  t=$({ time ffmpeg -hide_banner -loglevel error -y -i "$work/source.mkv" "$@" \
    "$out/$name.mp4" >/dev/null 2>&1; } 2>&1)
  printf 'ENCODE %-12s %6.2fs  %s\n' "$name" "$t" "$(du -h "$out/$name.mp4" | cut -f1)"
}
echo "$((secs * 30)) frames at $size on $(hostname)"
enc "$gpu_name" "${gpu[@]}"
enc x264 -c:v libx264 -preset medium -b:v 8M
